import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def parse_date(date_str):
    """Parse date string from various formats (YYYYMMDD, empty, etc.)"""
    if not date_str or date_str.strip() == "":
        return None
    # Try YYYYMMDD format
    if len(date_str) == 8 and date_str.isdigit():
        try:
            return datetime.strptime(date_str, "%Y%m%d").date()
        except ValueError:
            return None
    # Try other common formats if needed (not in this dataset)
    return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports from JSON file"""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r') as f:
        data = json.load(f)

    # Create mapping from recall_number to record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number", "")
        if recall_num:
            records[recall_num] = record
    return records

def process_pair(pair, rule_id, entity, fda_records, facts):
    """Process a single pair and return fact values"""
    result = {}

    if entity not in fda_records:
        # Entity not found in records
        for fact_name in facts[rule_id]:
            result[fact_name] = "ABSENT"
        return result

    record = fda_records[entity]

    # Map fact names to field names based on rules
    field_map = {
        "initiation date": "recall_initiation_date",
        "classification date": "center_classification_date",
        "termination date": "termination_date"
    }

    # Collect values for each fact
    fact_values = {}
    for fact_name in facts[rule_id]:
        field_name = field_map[fact_name]
        value = record.get(field_name, "")

        if not value or value.strip() == "":
            fact_values[fact_name] = "ABSENT"
        else:
            # Parse date to validate format
            parsed_date = parse_date(value)
            if parsed_date:
                # Format as YYYY-MM-DD
                formatted_date = parsed_date.strftime("%Y-%m-%d")
                fact_values[fact_name] = [formatted_date, "fda_enforcement_reports"]
            else:
                fact_values[fact_name] = "ABSENT"

    # Check for conflicts (multiple values for same fact)
    # In this dataset, each fact comes from only one document/field,
    # so no conflicts within the same entity
    result = fact_values

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Load FDA data
    fda_records = load_fda_data(packet_dir)

    # Process all pairs
    output = {}
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        result = process_pair(pair, rule_id, entity, fda_records, manifest["facts"])
        output[pair] = result

    # Print JSON output
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
