import json
import os
import sys
from datetime import datetime
from pathlib import Path

def parse_date(date_str):
    """Parse date string in YYYYMMDD format to datetime object."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%Y%m%d")
    except ValueError:
        return None

def date_to_iso(date_obj):
    """Convert datetime object to YYYY-MM-DD string."""
    if date_obj:
        return date_obj.strftime("%Y-%m-%d")
    return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports data from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r') as f:
        data = json.load(f)
    return data.get("results", [])

def find_recall_by_number(records, recall_number):
    """Find recall record by recall number."""
    for record in records:
        if record.get("recall_number") == recall_number:
            return record
    return None

def process_pair(pair, facts, records):
    """Process a single rule_id::entity pair and extract required facts."""
    rule_id, entity = pair.split("::", 1)
    required_facts = facts[rule_id]

    record = find_recall_by_number(records, entity)
    if not record:
        # If record not found, all facts are ABSENT
        return {fact: "ABSENT" for fact in required_facts}

    result = {}
    document = "fda_enforcement_reports"

    for fact in required_facts:
        if fact == "initiation date":
            value = record.get("recall_initiation_date")
            if not value or value.strip() == "":
                result[fact] = "ABSENT"
            else:
                date_obj = parse_date(value)
                if date_obj:
                    result[fact] = [date_to_iso(date_obj), document]
                else:
                    result[fact] = "ABSENT"

        elif fact == "classification date":
            value = record.get("center_classification_date")
            if not value or value.strip() == "":
                result[fact] = "ABSENT"
            else:
                date_obj = parse_date(value)
                if date_obj:
                    result[fact] = [date_to_iso(date_obj), document]
                else:
                    result[fact] = "ABSENT"

        elif fact == "termination date":
            value = record.get("termination_date")
            if not value or value.strip() == "":
